INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('817d3384952f30ff0a3b','AMEDEX 2025 Psychiatry (2).pdf','161','Mental Health','Janet is concerned about her 15-year-old son,
Joey, after she finds out he has been wearing
his older sister''s underwear. She is a single
parent, and her husband left them after Joey
was born. She works two jobs, has been
stressed, and has not had enough time to
spend with her kids. She is frustrated and
distressed with Joey''s behaviour, believes there
is something seriously wrong with him, and
wishes she had not given birth to him at all.
Which of the following is the correct statement
to share with Janet?','{"A":"Joey may feel as if he is a girl\ntrapped in a boy''s body.","B":"He is most likely doing it for fun.","C":"Not having a father figure in his life is\nthe reason for this behaviour.","D":"Janet''s lifestyle may be the main\nreason for Joey''s behaviour.","E":"It is a part of normal development at\nthis age."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-0fc8cb9ce2d7","duplicate_sources":[{"record_id":"817d3384952f30ff0a3b","record_type":"text_mcq","source_file":"AMEDEX 2025 Psychiatry (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry (2).pdf","source_page":161,"source_qid":null},{"record_id":"754f72fce95c26e7b10b","record_type":"text_mcq","source_file":"Psychiatry  Amedex 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Psychiatry  Amedex 2025.pdf","source_page":15,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"817d3384952f30ff0a3b","source_file":"AMEDEX 2025 Psychiatry (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Psychiatry (2).pdf","source_year":2025,"source_page":161,"source_qid":null,"domain_hint":"Mental Health","stem":"Janet is concerned about her 15-year-old son,\nJoey, after she finds out he has been wearing\nhis older sister''s underwear. She is a single\nparent, and her husband left them after Joey\nwas born. She works two jobs, has been\nstressed, and has not had enough time to\nspend with her kids. She is frustrated and\ndistressed with Joey''s behaviour, believes there\nis something seriously wrong with him, and\nwishes she had not given birth to him at all.\nWhich of the following is the correct statement\nto share with Janet?"