INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('806137f58b9485be33f3','AMEDEX 2025 Public health  (2).pdf','166','Ethics/Population Health','Christina, 38 years old, presents for
discussion about her risk of developing
ovarian cancer. Her detailed history shows
that she is the mother of four children, all
breastfed. She used oral contraceptive pills
for five years after the birth of her last child.
Two years ago, she underwent a
hysterectomy to ‘get rid of OCPs.’ Apart from
a BMI of 31, she is otherwise healthy on
